        elif "not" in keys:
            index_order(node_rule["not"], [*path, 0])

    index_order(rule, [])
    assert paths == expected

    # Every node is visited, including subtrees short-circuiting away from
    # the overall verdict (complete coverage, not a pruned trace).
    def count(node_rule):
